import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Button, Checkbox, Col, Form, Input, Row, Select } from 'antd'
import { get, isEqual } from 'lodash'

import { CreateWebhookStyle } from './index.style'
import PolicyActions from '../../../../../redux/policy/actions'

const FormItem = Form.Item
const { Option } = Select

const { getProducts } = PolicyActions

class CreateWebhook extends Component {
  state = {
    formValues: {}
  }

  handlePartnerChange = value => {
    this.props.getProducts({ query: { partner_code: value } })
  }

  componentDidMount () {
    const { formValues } = this.props
    if (formValues) {
      this.setState({ formValues })
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { formValues } = nextProps
    if (!isEqual(formValues, this.state.formValues)) {
      this.setState({ formValues: this.state.formValues })
    }
  }

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values = {}) => {
      if (!err) {
        const { formValues } = this.state
        if (values.product) {
          try {
            const productObject = JSON.parse(get(values, 'product'))
            values.product = get(productObject, 'name')
          } catch (e) { }
        }
        if (!values.authorization_type) {
          values.authorization_type = ''
        }
        this.props.handleSubmit({
          ...formValues,
          ...values
        })
      }
    })
  }

  render () {
    const {
      form, webhookEventType = [], webhookEventTypeLoading, partners = [],
      partnersLoading, products = [], productsLoading, editWebhook,
      webhookFunctions = [], webhookFunctionsLoading,
      webhookHeaders = [], webhookHeadersLoading

    } = this.props

    const { getFieldDecorator } = form
    const { formValues = {} } = this.state

    return (
      <CreateWebhookStyle>
        <Form onSubmit={this.handleSubmit}>
          <FormItem>
            {
              getFieldDecorator('is_active', {
                initialValue: get(formValues, 'is_active', true),
                valuePropName: 'checked'
              })(
                <Checkbox>
                  Is Active
                </Checkbox>)
            }
          </FormItem>
          <Row type='flex' justify='space-between'>
            <Col>
              <FormItem label='Partner'>
                {
                  getFieldDecorator('partner', {
                    rules: [{ required: true, message: 'Field cannot be empty!' }],
                    initialValue: get(formValues, 'partner')
                  }
                  )(
                    <Select
                      showSearch
                      allowClear
                      disabled={editWebhook}
                      placeholder='Select Partner'
                      dropdownMatchSelectWidth={false}
                      loading={!!partnersLoading}
                      onChange={this.handlePartnerChange}
                      filterOption={(input, option) =>
                        option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                    >
                      {
                        partners.map(({ name, code }) => <Option key={code} value={code}>{name}</Option>)
                      }
                    </Select>)
                }
              </FormItem>
            </Col>
            <Col>
              <FormItem label='Product'>
                {
                  getFieldDecorator('product', {
                    rules: [{ required: true, message: 'Field cannot be empty!' }],
                    initialValue: get(formValues, 'product')
                  })(
                    <Select
                      showSearch
                      allowClear
                      disabled={editWebhook}
                      placeholder='Select Product'
                      dropdownMatchSelectWidth={false}
                      loading={!!productsLoading}
                      filterOption={(input, option) =>
                        option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                    >
                      {
                        products.map(product => <Option key={JSON.stringify(product)} value={JSON.stringify(product)}>{get(product, 'name')}</Option>)
                      }
                    </Select>)
                }
              </FormItem>
            </Col>
          </Row>
          <Row type='flex' justify='space-between'>
            <Col>
              <FormItem label='Event'>
                {
                  getFieldDecorator('event_code_list', {
                    rules: [{ required: true, message: 'Field cannot be empty!' }],
                    initialValue: get(formValues, 'event_type') && [get(formValues, 'event_type', '')]
                  })(
                    <Select
                      showSearch
                      allowClear
                      mode='multiple'
                      disabled={editWebhook}
                      placeholder='Select Event'
                      dropdownMatchSelectWidth={false}
                      loading={!!webhookEventTypeLoading}
                      filterOption={(input, option) =>
                        option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                    >
                      {
                        webhookEventType.map(({ event_code: eventCode }) => <Option key={eventCode} value={eventCode}>{eventCode}</Option>)
                      }
                    </Select>)
                }
              </FormItem>
            </Col>
            <Col>
              <FormItem label='URL'>
                {
                  getFieldDecorator('url', {
                    rules: [{ required: true, message: 'Field cannot be empty!' }],
                    initialValue: get(formValues, 'url')
                  })(
                    <Input
                      placeholder='Input URL'
                    />)
                }
              </FormItem>
            </Col>
          </Row>
          <Row type='flex' justify='space-between'>
            <Col>
              <FormItem label='Function'>
                {
                  getFieldDecorator('function', {
                    rules: [{ required: true, message: 'Field cannot be empty!' }],
                    initialValue: get(formValues, 'function')
                  })(
                    <Select
                      showSearch
                      allowClear
                      placeholder='Select Function'
                      dropdownMatchSelectWidth={false}
                      loading={!!webhookFunctionsLoading}
                      filterOption={(input, option) =>
                        option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                    >
                      {
                        webhookFunctions.map(({ name }) => <Option key={name} value={name}>{name}</Option>)
                      }
                    </Select>)
                }
              </FormItem>
            </Col>
            <Col>
              <FormItem label='Header Key'>
                {
                  getFieldDecorator('header_key', {
                    initialValue: get(formValues, 'header_key')
                  })(
                    <Input
                      placeholder='Input Header Key'
                    />)
                }
              </FormItem>
            </Col>
          </Row>
          <Row type='flex' justify='space-between'>
            <Col>
              <FormItem label='Header Value'>
                {
                  getFieldDecorator('header_value', {
                    initialValue: get(formValues, 'header_value')
                  })(
                    <Input
                      placeholder='Input Header Value'
                    />)
                }
              </FormItem>
            </Col>
            <Col>
              <FormItem label='Authorization Type'>
                {
                  getFieldDecorator('authorization_type', {
                    initialValue: get(formValues, 'authorization_type')
                  })(
                    <Select
                      showSearch
                      allowClear
                      placeholder='Select Authorization Type'
                      dropdownMatchSelectWidth={false}
                      loading={!!webhookEventTypeLoading}
                      filterOption={(input, option) =>
                        option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                    >
                      <Option key='HMAC' value='HMAC'>HMAC</Option>
                      <Option key='Token' value='Token'>Token</Option>
                    </Select>)
                }
              </FormItem>
            </Col>
          </Row>

          <Row type='flex' justify='space-between'>
            <Col>
              <FormItem label='Recreate Header'>
                {
                  getFieldDecorator('recreate_headers', {
                    initialValue: get(formValues, 'recreate_headers'),
                    valuePropName: 'checked'
                  })(
                    <Checkbox>
                      Recreate Header
                    </Checkbox>
                  )
                }
              </FormItem>
            </Col>
          </Row>

          <Row type='flex' justify='space-between'>
            <Col>
              <FormItem label='Header Name'>
                {
                  getFieldDecorator('headers', {
                    rules: [{ required: false, message: 'Field cannot be empty!' }],
                    initialValue: get(formValues, 'headers')
                  })(

                    <Select
                      showSearch
                      allowClear
                      placeholder='Select Headers'
                      dropdownMatchSelectWidth={false}
                      loading={!!webhookHeadersLoading}
                      filterOption={(input, option) =>
                        option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                    >
                      {
                        webhookHeaders.map(({ name }) => <Option key={name} value={name}>{name}</Option>)
                      }
                    </Select>
                  )
                }
              </FormItem>
            </Col>
          </Row>
          <Row type='flex' justify='end'>
            <Button
              type='primary'
              htmlType='submit'
            >
              Submit
            </Button>
          </Row>
        </Form>

      </CreateWebhookStyle>
    )
  }
}

const WrappedCreateWebhook = Form.create()(CreateWebhook)

export default connect(state => ({
  partners: state.Policy.partners,
  partnersLoading: state.Loading.GET_PARTNERS,

  products: state.Policy.products,
  productsLoading: state.Loading.GET_PRODUCTS,

  webhookEventType: state.IL.webhookEventType,
  webhookEventTypeLoading: state.Loading.GET_EVENT_TYPE,

  webhookFunctions: state.IL.webhookFunctions,
  webhookFunctionsLoading: state.Loading.GET_FUNCTIONS,

  webhookHeaders: state.IL.webhookHeaders,
  webhookHeadersLoading: state.Loading.GET_HEADERS
}), {
  getProducts
})(WrappedCreateWebhook)
