import { Table } from 'antd'
import React, { Component } from 'react'
import { connect } from 'react-redux'
import { WebhookListStyle } from './index.style'

class WebhookList extends Component {
  render () {
    const { webhookList = [], webhookListLoading } = this.props
    const columns = [{
      key: 'action',
      dataIndex: 'id',
      title: 'Action',
      render: (_, data) => <div className='edit-button' onClick={() => this.props.handleEdit(data)}>Edit</div>
    }, {
      key: 'event_type',
      dataIndex: 'event_type',
      title: 'Events'
    }, {
      key: 'partner',
      dataIndex: 'partner',
      title: 'Partner'
    }, {
      key: 'product',
      dataIndex: 'product',
      title: 'Product'
    }, {
      key: 'function',
      dataIndex: 'function',
      title: 'Function'
    }, {
      key: 'authorization_type',
      dataIndex: 'authorization_type',
      title: 'Authorization Type'
    }, {
      key: 'is_active',
      dataIndex: 'is_active',
      title: 'Status',
      render: value => value ? 'Active' : 'Inactive'
    }, {
      key: 'header_key',
      dataIndex: 'header_key',
      title: 'Header Key'
    }, {
      key: 'header_value',
      dataIndex: 'header_value',
      title: 'Header Value'
    }, {
      key: 'url',
      dataIndex: 'url',
      title: 'URL'
    }, {
      key: 'headers',
      dataIndex: 'headers',
      title: 'Header Name'
    }, {
      key: 'recreate_headers',
      dataIndex: 'recreate_headers',
      title: 'Recreate Header',
      render: value => value ? 'True' : 'False'
    }]

    return (
      <WebhookListStyle>
        <Table
          dataSource={webhookList}
          columns={columns}
          loading={!!webhookListLoading}
        />
      </WebhookListStyle>
    )
  }
}

export default connect(state => ({
  webhookList: state.IL.webhookList,
  webhookListLoading: state.Loading.GET_WEBHOOK_LIST
}), {
})(WebhookList)
