import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Button, Modal, notification, Row } from 'antd'

import { WebhookStyle } from './index.style'
import { Filters, WebhookList, CreateWebhook } from './components'
import PolicyActions from '../../../redux/policy/actions'
import ILActions from '../../redux/il/action'
import errorAction from '../../../redux/error/actions'
import loadingAction from '../../../redux/loading/actions'

const { getPartners, getProducts } = PolicyActions
const { getEventType, getWebhookList, createWebhook, updateWebhook, getFunctions, getHeaders } = ILActions
const { resetLoadingRedux } = loadingAction
const { resetErrorRedux } = errorAction

class Webhook extends Component {
  state = {
    showCreateWebhookModal: false,
    values: {},
    filterValues: {}
  }

  componentDidMount () {
    this.props.getPartners()
    this.props.getProducts()
    this.props.getEventType()
    this.props.getFunctions()
    this.props.getHeaders()
    this.props.getWebhookList()
    this.props.resetLoadingRedux(['CREATE_WEBHOOK', 'UPDATE_WEBHOOK'])
    this.props.resetErrorRedux(['CREATE_WEBHOOK', 'UPDATE_WEBHOOK'])
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      createWebhookLoading, createWebhookError, createWebhookMessage,
      updateWebhookLoading, updateWebhookError, updateWebhookMessage
    } = nextProps
    const { filterValues } = this.state

    if (createWebhookLoading === false) {
      notification[createWebhookError ? 'error' : 'success']({ message: 'Error', description: createWebhookMessage, style: { overflowWrap: 'break-word' } })
      if (createWebhookError === false) {
        this.setState({ showCreateWebhookModal: false })
        this.onHandleSubmit(filterValues)
      }
      this.props.resetLoadingRedux(['CREATE_WEBHOOK'])
      this.props.resetErrorRedux(['CREATE_WEBHOOK'])
    }

    if (updateWebhookLoading === false) {
      notification[updateWebhookError ? 'error' : 'success']({ message: updateWebhookMessage })
      if (updateWebhookError === false) {
        this.setState({ showCreateWebhookModal: false })
        this.onHandleSubmit(filterValues)
      }
      this.props.resetLoadingRedux(['UPDATE_WEBHOOK'])
      this.props.resetErrorRedux(['UPDATE_WEBHOOK'])
    }
  }

  handleCreateWebhookClick = () => {
    this.props.getPartners()
    this.props.getProducts()
    this.setState({ showCreateWebhookModal: true, editWebhook: false, values: {} })
  }

  onHandleSubmit = (values) => {
    this.setState({ values, filterValues: values })
    this.props.getWebhookList({
      query: values
    })
  }

  onHandleCreateWebhook = values => {
    const { editWebhook } = this.state

    if (editWebhook) {
      this.props.updateWebhook({
        body: values
      })
    } else {
      this.props.createWebhook({
        body: values
      })
    }
  }

  onHandleEdit = (values) => {
    this.setState({ editWebhook: true, showCreateWebhookModal: true, values })
  }

  render () {
    const { values, showCreateWebhookModal, editWebhook } = this.state

    return (
      <WebhookStyle>
        {
          showCreateWebhookModal &&
            <Modal
              visible
              title={editWebhook ? 'Edit Webhook' : 'Create Webhook'}
              footer={null}
              onCancel={() => this.setState({ showCreateWebhookModal: false, editWebhook: false })}
              width={600}
            >
              <CreateWebhook
                formValues={values}
                handleSubmit={this.onHandleCreateWebhook}
                visible={showCreateWebhookModal}
                editWebhook={editWebhook}
              />
            </Modal>
        }
        <Filters
          handleSubmit={this.onHandleSubmit}
        />
        <Row type='flex' justify='end'>
          <Button
            type='primary'
            onClick={this.handleCreateWebhookClick}
          >
            Create Webhook
          </Button>
        </Row>
        <WebhookList
          handleEdit={this.onHandleEdit}
        />
      </WebhookStyle>
    )
  }
}

export default connect(state => ({
  partners: state.Policy.partners,

  createWebhookLoading: state.Loading.CREATE_WEBHOOK,
  createWebhookError: state.Error.CREATE_WEBHOOK,
  createWebhookMessage: state.IL.createWebhookMessage,

  updateWebhookLoading: state.Loading.UPDATE_WEBHOOK,
  updateWebhookError: state.Error.UPDATE_WEBHOOK,
  updateWebhookMessage: state.IL.updateWebhookMessage
}), {
  getPartners,
  getProducts,
  getEventType,
  getWebhookList,
  createWebhook,
  updateWebhook,
  getFunctions,
  getHeaders,
  resetLoadingRedux,
  resetErrorRedux
})(Webhook)
